import re
ABBREV_RE = re.compile(r'\\b(?:[A-Za-z]\\.){2,}')

def _strip_dotted_abbrev(text: str) -> str:
    return ABBREV_RE.sub(lambda m: m.group(0).replace('.', ''), text)

def _split_sentences(text: str) -> list[str]:
    cleaned = _strip_dotted_abbrev(text.strip())
    return [s.strip() for s in nltk.sent_tokenize(cleaned) if len(s.strip()) > 5]
